return ['domain'=>'wp-seo-multilingual','plural-forms'=>'nplurals=3; plural=(n%10==1 && n%100!=11 ? 0 : n%10>=2 && n%10<=4 && (n%100<10 || n%100>=20) ? 1 : 2);','language'=>'uk','project-id-version'=>'WPML SEO 5.2.0','pot-creation-date'=>'2026-10-20 07:35+0000','po-revision-date'=>'2026-10-20 07:35+0000','x-generator'=>'PTC (Private Translation Cloud)','messages'=>['WPML SEO'=>'WPML SEO','https://wpml.org/documentation/wpml-core-and-add-on-plugins/wpml-seo/'=>'https://wpml.org/documentation/wpml-core-and-add-on-plugins/wpml-seo/','Multilingual support for popular SEO plugins'=>'Мультимовна підтримка для популярних SEO-плагінів','OnTheGoSystems'=>'OnTheGoSystems','http://www.onthegosystems.com/'=>'http://www.onthegosystems.com/','Hreflang tags moved to your sitemap'=>'Теги hreflang перенесено до вашої мапи сайту','To improve SEO and avoid duplicate hreflang data, WPML now adds hreflang tags only to your sitemap. We have disabled the hreflang tags in your page\'s <head> section.'=>'Щоб покращити SEO та уникнути дублювання даних hreflang, WPML тепер додає теги hreflang лише до вашої мапи сайту. Ми вимкнули теги hreflang у розділі <head> вашої сторінки.','If you prefer to keep them in the <head>, you can re-enable this option in %1$sWPML → Settings → URLs and SEO%2$s.'=>'Якщо ви бажаєте залишити їх у <head>, ви можете знову ввімкнути цю опцію в розділі %1$sWPML → Налаштування → URL-адреси та SEO%2$s.','Sitemaps for each language'=>'Мапи сайту для кожної мови','Each language runs on its own domain, so each one has its own sitemap. Submit all of them to Google Search Console.'=>'Кожна мова працює на власному домені, тому кожна має свою мапу сайту. Надішліть їх усі до Google Search Console.','Translated by WPML'=>'Перекладено WPML','This field shows the translation that WPML String Translation serves. Click "Edit anyway" to override it.'=>'У цьому полі відображається переклад, який надає WPML String Translation. Натисніть «Усе одно редагувати», щоб перевизначити його.','Edit anyway'=>'Усе одно редагувати','Your text overrides the WPML translation. Leave the field empty to let WPML translate it.'=>'Ваш текст перевизначає переклад WPML. Залиште поле порожнім, щоб дозволити WPML перекласти його.','This section has the Yoast SEO texts of your categories, tags and other taxonomy terms.'=>'Цей розділ містить тексти Yoast SEO ваших категорій, позначок та інших елементів таксономії.']];